action.command:
cd /workspace/services/ingestion && cat > test_queue.ts << 'EOF'
import * as dotenv from 'dotenv';
dotenv.config({ override: true });

import { rawEventsQueue } from './src/queue';

async function test() {
  console.log('[queue] Testing BullMQ connection...');
  console.log('[queue] Redis URL:', process.env.REDIS_URL);

  try {
    // Test adding a job to the queue
    const jobId = `test-${Date.now()}`;
    await rawEventsQueue.add('test-job', {
      source: 'test',
      source_id: 'test-123',
      title: 'Test Event',
      start_date: '2026-03-27',
      start_time: '19:00',
    }, { jobId });

    console.log('[queue] ✅ Job added successfully:', jobId);

    // Check queue counts
    const counts = await rawEventsQueue.getJobCounts();
    console.log('[queue] Queue counts:', counts);

    // Clean up test job
    await rawEventsQueue.remove(jobId);
    console.log('[queue] Test job removed');

  } catch (error) {
    console.error('[queue] ❌ Error:', error);
  }
}

test();
EOF
npx tsx test_queue.ts 2>&1

